import{_ as l,I as i,o as r,c as h,b6 as a,J as t}from"./chunks/framework.COUcLbTA.js";const _=JSON.parse('{"title":"开源协作","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/9-engineering-excellence/open-source-collaboration.md","filePath":"zh-cn/appendix/9-engineering-excellence/open-source-collaboration.md"}'),o={name:"zh-cn/appendix/9-engineering-excellence/open-source-collaboration.md"};function d(p,s,c,k,g,b){const e=i("OpenSourceWorkflowDemo"),n=i("LicenseComparisonDemo");return r(),h("div",null,[s[0]||(s[0]=a('<h1 id="开源协作" tabindex="-1">开源协作 <a class="header-anchor" href="#开源协作" aria-label="Permalink to “开源协作”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p><strong>想参与开源项目但不知道从哪开始？</strong> 开源不只是&quot;免费用别人的代码&quot;，更是一种协作方式和职业加速器。一次高质量的开源贡献，可能比简历上写十个个人项目更有说服力。</p><p>本章带你理解开源协作的完整流程，从找项目到提交 PR，迈出开源贡献的第一步。</p></div><p><strong>这篇文章会带你学什么？</strong></p><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>核心概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>开源贡献流程</td><td>Fork → PR 的完整链路</td></tr><tr><td><strong>第 2 章</strong></td><td>开源许可证</td><td>不同许可证的区别</td></tr><tr><td><strong>第 3 章</strong></td><td>协作礼仪</td><td>如何做一个受欢迎的贡献者</td></tr><tr><td><strong>第 4 章</strong></td><td>从零开始贡献</td><td>找到适合新手的项目</td></tr></tbody></table><p>学完本章，你将掌握开源协作的完整流程和礼仪，有信心向任何开源项目提交贡献。</p><hr><h2 id="_0-全景图-开源的价值" tabindex="-1">0. 全景图：开源的价值 <a class="header-anchor" href="#_0-全景图-开源的价值" aria-label="Permalink to “0. 全景图：开源的价值”">​</a></h2><p>开源不只是代码共享，更是一种<strong>全球化的协作模式</strong>。Linux、React、Vue、Node.js——这些改变世界的项目都是开源的。</p><div class="tip custom-block"><p class="custom-block-title">参与开源的好处</p><ul><li><strong>技术成长</strong>：阅读优秀代码，接受高手 Review</li><li><strong>职业发展</strong>：开源贡献是最好的技术名片</li><li><strong>社区归属</strong>：成为全球开发者社区的一员</li><li><strong>回馈生态</strong>：你每天用的工具，也需要有人维护</li></ul></div><hr><h2 id="_1-开源贡献流程" tabindex="-1">1. 开源贡献流程 <a class="header-anchor" href="#_1-开源贡献流程" aria-label="Permalink to “1. 开源贡献流程”">​</a></h2><p>通过下面的交互组件，逐步了解从 Fork 到 Merge 的完整流程：</p>',12)),t(e),s[1]||(s[1]=a('<h3 id="_1-1-流程概览" tabindex="-1">1.1 流程概览 <a class="header-anchor" href="#_1-1-流程概览" aria-label="Permalink to “1.1 流程概览”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Fork → Clone → Branch → Commit → Push → PR → Review → Merge</span></span></code></pre></div><h3 id="_1-2-关键步骤详解" tabindex="-1">1.2 关键步骤详解 <a class="header-anchor" href="#_1-2-关键步骤详解" aria-label="Permalink to “1.2 关键步骤详解”">​</a></h3><p><strong>创建功能分支</strong>：不要直接在 main 上开发。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fix/typo-in-readme</span></span></code></pre></div><p><strong>写清晰的 Commit Message</strong>：遵循项目的提交规范。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fix: 修复 README 中的安装命令拼写错误&quot;</span></span></code></pre></div><p><strong>创建 Pull Request</strong>：PR 描述应包含：</p><ul><li>改了什么、为什么改</li><li>关联的 Issue 编号（如 <code>Fixes #123</code>）</li><li>如何测试你的改动</li></ul><hr><h2 id="_2-开源许可证" tabindex="-1">2. 开源许可证 <a class="header-anchor" href="#_2-开源许可证" aria-label="Permalink to “2. 开源许可证”">​</a></h2><p>通过下面的交互组件，对比常见开源许可证的区别：</p>',12)),t(n),s[2]||(s[2]=a(`<h3 id="_2-1-常见许可证" tabindex="-1">2.1 常见许可证 <a class="header-anchor" href="#_2-1-常见许可证" aria-label="Permalink to “2.1 常见许可证”">​</a></h3><table tabindex="0"><thead><tr><th>许可证</th><th>特点</th><th>典型项目</th></tr></thead><tbody><tr><td><strong>MIT</strong></td><td>最宽松，几乎无限制</td><td>React, Vue, jQuery</td></tr><tr><td><strong>Apache 2.0</strong></td><td>需保留版权声明，有专利授权</td><td>Android, Kubernetes</td></tr><tr><td><strong>GPL</strong></td><td>衍生作品必须也开源</td><td>Linux, WordPress</td></tr><tr><td><strong>BSD</strong></td><td>类似 MIT，略有不同</td><td>FreeBSD, Flask</td></tr></tbody></table><h3 id="_2-2-如何选择" tabindex="-1">2.2 如何选择？ <a class="header-anchor" href="#_2-2-如何选择" aria-label="Permalink to “2.2 如何选择？”">​</a></h3><ul><li><strong>想让更多人用</strong>：选 MIT</li><li><strong>想保护专利</strong>：选 Apache 2.0</li><li><strong>想确保衍生品也开源</strong>：选 GPL</li></ul><hr><h2 id="_3-协作礼仪" tabindex="-1">3. 协作礼仪 <a class="header-anchor" href="#_3-协作礼仪" aria-label="Permalink to “3. 协作礼仪”">​</a></h2><h3 id="_3-1-提-issue-的礼仪" tabindex="-1">3.1 提 Issue 的礼仪 <a class="header-anchor" href="#_3-1-提-issue-的礼仪" aria-label="Permalink to “3.1 提 Issue 的礼仪”">​</a></h3><div class="language-markdown"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 差 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">标题：不能用了</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">内容：你们的东西有 bug</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 好 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">标题：v2.1.0 在 Safari 17 下登录页白屏</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">内容：</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 环境：macOS 14.2, Safari 17.2</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 复现步骤：1. 打开登录页 2. 输入账号密码 3. 点击登录</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 期望行为：跳转到首页</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 实际行为：页面白屏，控制台报错 TypeError: xxx</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 截图：[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">附图</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h3 id="_3-2-提-pr-的礼仪" tabindex="-1">3.2 提 PR 的礼仪 <a class="header-anchor" href="#_3-2-提-pr-的礼仪" aria-label="Permalink to “3.2 提 PR 的礼仪”">​</a></h3><ul><li>先看 <code>CONTRIBUTING.md</code>，了解项目的贡献规范</li><li>一个 PR 只做一件事，不要混合多个改动</li><li>保持 PR 小而聚焦，方便 Review</li><li>耐心等待 Review，礼貌回应反馈</li></ul><h3 id="_3-3-review-他人代码" tabindex="-1">3.3 Review 他人代码 <a class="header-anchor" href="#_3-3-review-他人代码" aria-label="Permalink to “3.3 Review 他人代码”">​</a></h3><ul><li>先肯定做得好的地方，再提改进建议</li><li>提问而不是命令：&quot;这里是否考虑过用 X 方案？&quot;</li><li>给出理由和替代方案，而不只是说&quot;不好&quot;</li></ul><hr><h2 id="_4-从零开始贡献" tabindex="-1">4. 从零开始贡献 <a class="header-anchor" href="#_4-从零开始贡献" aria-label="Permalink to “4. 从零开始贡献”">​</a></h2><h3 id="_4-1-适合新手的贡献类型" tabindex="-1">4.1 适合新手的贡献类型 <a class="header-anchor" href="#_4-1-适合新手的贡献类型" aria-label="Permalink to “4.1 适合新手的贡献类型”">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td>修复文档错误</td><td>低</td><td>错别字、过时链接、不清晰的说明</td></tr><tr><td>翻译</td><td>低</td><td>将文档翻译为其他语言</td></tr><tr><td>补充测试</td><td>中</td><td>为未覆盖的代码添加测试</td></tr><tr><td>修复标记为 <code>good first issue</code> 的 Bug</td><td>中</td><td>项目维护者标记的新手友好问题</td></tr><tr><td>新功能</td><td>高</td><td>先在 Issue 中讨论方案，获得认可后再动手</td></tr></tbody></table><h3 id="_4-2-找到合适的项目" tabindex="-1">4.2 找到合适的项目 <a class="header-anchor" href="#_4-2-找到合适的项目" aria-label="Permalink to “4.2 找到合适的项目”">​</a></h3><ul><li>从你日常使用的工具开始</li><li>GitHub 搜索 <code>good first issue</code> 标签</li><li>关注项目的活跃度（最近是否有人维护）</li></ul><hr><h2 id="_5-ai-助力-用大模型加速开源贡献" tabindex="-1">5. AI 助力：用大模型加速开源贡献 <a class="header-anchor" href="#_5-ai-助力-用大模型加速开源贡献" aria-label="Permalink to “5. AI 助力：用大模型加速开源贡献”">​</a></h2><p>大模型可以帮你快速理解陌生代码库、写出高质量的 PR 描述、甚至辅助 Code Review。</p><h3 id="_5-1-快速理解陌生代码库" tabindex="-1">5.1 快速理解陌生代码库 <a class="header-anchor" href="#_5-1-快速理解陌生代码库" aria-label="Permalink to “5.1 快速理解陌生代码库”">​</a></h3><blockquote><p><strong>提示词</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我刚 clone 了一个开源项目，请帮我分析以下目录结构，</span></span>
<span class="line"><span>说明每个目录/文件的职责，以及代码的整体架构和数据流向。</span></span>
<span class="line"><span>我想修复一个登录相关的 Bug，应该从哪里开始看？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴 tree 命令输出或目录结构]</span></span></code></pre></div></blockquote><h3 id="_5-2-写-pr-描述" tabindex="-1">5.2 写 PR 描述 <a class="header-anchor" href="#_5-2-写-pr-描述" aria-label="Permalink to “5.2 写 PR 描述”">​</a></h3><blockquote><p><strong>提示词</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>根据以下 git diff，帮我写一份 Pull Request 描述，包括：</span></span>
<span class="line"><span>- 标题（简洁，说明改了什么）</span></span>
<span class="line"><span>- 改动说明（为什么改、改了什么）</span></span>
<span class="line"><span>- 测试方法（如何验证改动正确）</span></span>
<span class="line"><span>- 关联 Issue（如果有）</span></span>
<span class="line"><span>用英文撰写，语气专业友好。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴 git diff 输出]</span></span></code></pre></div></blockquote><h3 id="_5-3-辅助翻译文档" tabindex="-1">5.3 辅助翻译文档 <a class="header-anchor" href="#_5-3-辅助翻译文档" aria-label="Permalink to “5.3 辅助翻译文档”">​</a></h3><blockquote><p><strong>提示词</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>将以下中文技术文档翻译为英文，要求：</span></span>
<span class="line"><span>1. 技术术语使用业界通用的英文表达</span></span>
<span class="line"><span>2. 代码注释和变量名不翻译</span></span>
<span class="line"><span>3. 保持 Markdown 格式不变</span></span>
<span class="line"><span>4. 语气自然流畅，不要机翻感</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴中文文档]</span></span></code></pre></div></blockquote><div class="tip custom-block"><p class="custom-block-title">AI 使用建议</p><p>用 AI 写 PR 描述时，确保你自己理解了每一行改动。审查者可能会问你为什么这么改——如果你答不上来，说明你还没真正理解。</p></div><hr><h2 id="_6-总结" tabindex="-1">6. 总结 <a class="header-anchor" href="#_6-总结" aria-label="Permalink to “6. 总结”">​</a></h2><ol><li><strong>流程</strong>：Fork → Branch → Commit → PR → Review → Merge</li><li><strong>许可证</strong>：MIT 最宽松，GPL 最严格，根据需求选择</li><li><strong>礼仪</strong>：清晰的 Issue、聚焦的 PR、礼貌的沟通</li><li><strong>起步</strong>：从文档修复和 <code>good first issue</code> 开始</li></ol><div class="tip custom-block"><p class="custom-block-title">终极思考</p><p>开源的本质是<strong>协作</strong>。技术能力固然重要，但沟通能力、协作意识同样关键。一个态度友好、描述清晰的 PR，比一个代码完美但沟通粗暴的 PR 更受欢迎。<strong>你的第一个 PR 不需要完美，只需要迈出第一步。</strong></p></div><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><strong>入门指南</strong>：GitHub 的 Open Source Guide 是最好的开源入门资源。</li><li><strong>实践建议</strong>：找一个你喜欢的项目，先 Star，再读代码，最后找机会贡献。</li><li><strong>社区参与</strong>：参加 Hacktoberfest 等开源活动，获得社区支持。</li><li><strong>维护者视角</strong>：了解维护者的工作量和压力，做一个体贴的贡献者。</li></ul>`,35))])}const m=l(o,[["render",d]]);export{_ as __pageData,m as default};
